(()=>{if((window.scc??(window.scc={})).services)return;window.scc.services=!0;const c=n=>{const e=n.querySelector(".service-head"),i=n.querySelector(".service-body");if(!e||!i)return;n.classList.remove("is-open"),e.setAttribute("role","button"),e.setAttribute("tabindex","0"),e.setAttribute("aria-expanded","false");const r=()=>{const t=!n.classList.contains("is-open");n.classList.toggle("is-open",t),e.setAttribute("aria-expanded",String(t))};e.addEventListener("click",r),e.addEventListener("keydown",t=>{t.key!=="Enter"&&t.key!==" "||(t.preventDefault(),r())})},s=()=>document.querySelectorAll(".service-item").forEach(c);document.readyState==="loading"?document.addEventListener("DOMContentLoaded",s,{once:!0}):s()})();
